import { Component, h, Prop, Host, ComponentInterface, Element } from '@stencil/core';
import { Slot, Slots } from '@src/framework/decorators';

function _getTargetParentComponent<T extends HTMLElement>(node: HTMLElement, className: string): T | undefined {
  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  function find(node) {
    if (!node) {
      return undefined;
    }
    if (node.classList?.contains(className)) {
      return node;
    }
    return find(node?.parentNode || node?.host);
  }

  return find(node);
}

/**
 * @slot header - Content for the tab's header/label. This content will be displayed in the tab bar by the parent `ks-tabs` component.
 * @slot default - Content for the tab panel shown when the item is active.
 */
@Component({
  tag: 'ks-tab-item',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsTabItem implements ComponentInterface {
  @Element() el!: HTMLKsTabItemElement;

  /** The unique ID of the current tab item. Use a unique value so `ks-tabs` can match the header and panel content correctly. */
  @Prop() tabId?: string;
  /** Indicates whether the current tab is disabled. When `true`, the user will not be able to interact with the tab. */
  @Prop() disabled = false;

  @Slot({ slotname: 'header' }) headerSlot?: Slots<HTMLElement & { tabid?: string }>;

  componentDidLoad(): void {
    const parent = _getTargetParentComponent<HTMLElement>(this.el, 'KsTabs');
    if (!parent) {
      return;
    }

    if (parent.querySelectorAll('slot[name="header"]').length > 0) {
      parent.querySelectorAll('slot[name="header"]').forEach((el) => el.remove());
    }

    this.headerSlot?.map((item) => {
      if (!this.tabId) return;

      item.slot = this.tabId;
      item.id = this.tabId;
      const children = Array.from(parent.childNodes) as HTMLElement[];
      const child = children.find((item) => item.id === this.tabId);
      if (child) {
        parent.removeChild(parent.querySelector(`#${this.tabId}`) as Node);
      }
      parent.appendChild(item);
    });
  }

  render() {
    return (
      <Host class="KsTabItem" role="tabpanel">
        <slot name="header"></slot>
        <slot></slot>
      </Host>
    );
  }
}
